 private val lock = Any()

 class AppModule(val app: Application) : InjektModule {

     private var sqlDriverRef: WeakReference<SqlDriver>? = null

     override fun InjektRegistrar.registerInjectables() {
         addSingleton(app)

         addSingletonFactory<SqlDriver> {
             synchronized(lock) {
                 sqlDriverRef?.get()?.let { return@synchronized it }

                 AndroidxSqliteDriver(
                     driver = BundledSQLiteDriver(),
                     databaseType = AndroidxSqliteDatabaseType.FileProvider(app, "tachiyomi.db"),
                     schema = Database.Schema,
                     configuration = AndroidxSqliteConfiguration(
                         isForeignKeyConstraintsEnabled = true,
                     ),
                 )
                     .also { sqlDriverRef = WeakReference(it) }
             }
         }
         addSingletonFactory {
             Database(
                 driver = get(),
                 historyAdapter = History.Adapter(
                     last_readAdapter = DateColumnAdapter,
                 ),
                 mangasAdapter = Mangas.Adapter(
                     genreAdapter = StringListColumnAdapter,
                     update_strategyAdapter = UpdateStrategyColumnAdapter,
                     memoAdapter = MemoColumnAdapter,
                 ),
                 chaptersAdapter = Chapters.Adapter(
                     memoAdapter = MemoColumnAdapter,
                 ),
             )
         }

         addSingletonFactory {
             Json {
                 ignoreUnknownKeys = true
                 explicitNulls = false
+                // Ответы трекеров и источников приходят неполными: вместо
+                // «pages»: null или «rating»: "N/A" раньше падал весь разбор
+                // ответа. Теперь такое значение заменяется дефолтом типа.
+                coerceInputValues = true
             }
         }
         addSingletonFactory<XML> {
             XML.v1 {
                 policy {
                     ignoreUnknownChildren()
                     autoPolymorphic = true
                 }
                 xmlDeclMode = XmlDeclMode.Charset
                 xmlVersion = XmlVersion.XML10
                 setIndent(2)
             }
         }
         addSingletonFactory<ProtoBuf> {
             ProtoBuf
         }

         addSingletonFactory { ChapterCache(app, get()) }
         addSingletonFactory { CoverCache(app) }

         addSingletonFactory { NetworkHelper(app, get()) }
         addSingletonFactory { JavaScriptEngine(app) }

         addSingletonFactory<SourceManager> { AndroidSourceManager(app, get(), get()) }
         addSingletonFactory { ExtensionManager(app) }

         addSingletonFactory { DownloadProvider(app) }
         addSingletonFactory { DownloadManager(app) }
         addSingletonFactory { DownloadCache(app) }

         addSingletonFactory { TrackerManager() }
         addSingletonFactory { DelayedTrackingStore(app) }

         addSingletonFactory { ImageSaver(app) }

         addSingletonFactory { AndroidStorageFolderProvider(app) }
         addSingletonFactory { LocalSourceFileSystem(get()) }
         addSingletonFactory { LocalCoverManager(app, get()) }
         addSingletonFactory { StorageManager(app, get()) }

         // Asynchronously init expensive components for a faster cold start
         ContextCompat.getMainExecutor(app).execute {
             get<NetworkHelper>()

             get<SourceManager>()

             get<Database>()

             get<DownloadManager>()
         }
     }
 }

