     private fun textButton(symbol: String, onClick: () -> Unit): Button {
         val b = Button(this)
         b.text = symbol
         b.textSize = 11f
         b.setAllCaps(false)
         b.setPadding(dp(5f), 0, dp(5f), 0)
         b.setBackgroundColor(0xFF2E4A6B.toInt())
