             chapterIds = chapterIds,
         )
     }

     override suspend fun clearCachedChapter(chapterId: Long) {
         cacheStore.clearChapter(chapterId)
     }

     override suspend fun clearCache() {
         cacheStore.clear()
     }

     override suspend fun getCacheSizeBytes(): Long {
