    return RectF(
        min(topLeftLocal.x, bottomRightLocal.x),
        min(topLeftLocal.y, bottomRightLocal.y),
        max(topLeftLocal.x, bottomRightLocal.x),
        max(topLeftLocal.y, bottomRightLocal.y),
    )
}

