/**
 * Вкладки нижней навигации приложения.
 *
 * Id стабильные и живут в файлах пользователя, поэтому их нельзя брать из имени
 * класса: в release-сборке R8 переименовывает классы. Порядок объявлений —
 * порядок вкладок в навигации.
 *
 * @param pinned вкладку нельзя скрыть: без неё приложение останется либо без
 *   контента ([LIBRARY]), либо без входа в настройки ([MORE]), и вернуть её
 *   будет нечем.
 */
enum class UiTab(val id: String, val title: String, val pinned: Boolean = false) {
    LIBRARY("library", "Библиотека", pinned = true),
    LOCAL_LIBRARY("local_library", "Локальная библиотека"),
    UPDATES("updates", "Обновления"),
    HISTORY("history", "История"),
    BROWSE("browse", "Каталоги"),
    BROWSER("browser", "Браузер"),
    AI("ai", "AI-чат"),
    SCREENSHOTS("screenshots", "Скриншоты"),
    MORE("more", "Ещё", pinned = true),
    ;

    companion object {
        fun fromId(id: String?): UiTab? =
            entries.firstOrNull { it.id == id?.trim()?.lowercase() }
    }
}

/**
 * Правила видимости вкладок: чистые функции без Android, чтобы их можно было
 * проверить юнит-тестами.
 */
object UiTabs {

    /** Все id в порядке показа. */
    val IDS: List<String> = UiTab.entries.map { it.id }

    /** Id, которые нельзя скрыть ни через чат, ни правкой файла. */
    val PROTECTED_IDS: Set<String> = UiTab.entries.filter { it.pinned }.map { it.id }.toSet()

    /**
     * Причина, по которой id не годится, или `null`, если годится.
     *
     * Текст причины показывается пользователю и агенту, поэтому он всегда
     * содержит список допустимых значений.
     */
    fun validate(id: String): String? {
        val key = id.trim().lowercase()
        return when {
            key.isEmpty() -> "Пустой id вкладки"
            key !in IDS -> "Неизвестная вкладка «$key». Доступны: ${IDS.joinToString()}"
            key in PROTECTED_IDS ->
                "Вкладку «$key» нельзя скрыть: без неё не останется библиотеки или входа в настройки"
            else -> null
        }
    }

    /** Скрыта ли вкладка. Закреплённые не скрываются никогда. */
    fun isHidden(id: String, hidden: Set<String>): Boolean {
        val key = id.trim().lowercase()
        return key in hidden && key !in PROTECTED_IDS
    }

    /**
     * Оставить только видимые вкладки, сохранив порядок [ids].
     *
     * Защита применяется и здесь: файл `workspace/ui/tabs.json` пользователь
     * может править руками или залить из архива чужого workspace.
     */
    fun visibleTabs(ids: List<String>, hidden: Set<String>): List<String> =
        ids.filterNot { isHidden(it, hidden) }

    /** Выкинуть неизвестные, закреплённые и пустые id, привести к нижнему регистру. */
    fun sanitizeHidden(ids: Collection<String>): Set<String> =
        ids.map { it.trim().lowercase() }
            .filter { it in IDS && it !in PROTECTED_IDS }
            .toSet()
}

@Suppress("ConstPropertyName")
private const val TabFadeDuration = 200

@Suppress("ConstPropertyName")
private const val TabNavigatorKey = "HomeTabs"

/**
 * Вкладки вместе со стабильными id из реестра [UiTabs]. Id нельзя брать из
 * имени класса: в release-сборке R8 переименовывает классы, а id живут в
 * файлах пользователя.
 */
private val TABS = listOf(
    UiTab.LIBRARY to LibraryTab,
    UiTab.LOCAL_LIBRARY to eu.kanade.tachiyomi.ui.locallibrary.LocalLibraryTab,
    UiTab.UPDATES to UpdatesTab,
    UiTab.HISTORY to HistoryTab,
    UiTab.BROWSE to BrowseTab,
    UiTab.BROWSER to eu.kanade.tachiyomi.ui.webbrowser.BrowserTab,
    UiTab.AI to eu.kanade.tachiyomi.ui.aichat.AiChatTab,
    UiTab.SCREENSHOTS to eu.kanade.tachiyomi.ui.screenshots.ScreenshotTab,
    UiTab.MORE to MoreTab,
)

/**
 * Видимые вкладки.
 *
 * «AI» скрывается в её же настройках (агент тогда доступен из внешнего
 * браузера через встроенный сервер), остальные — через реестр [UiTabRegistry]
 * (AI-чат: `ui_tab_hide` / `ui_tab_show`, либо файл `workspace/ui/tabs.json`).
 * Библиотека и «Ещё» закреплены в [UiTabs.PROTECTED_IDS]: без них приложение
 * останется без контента или без входа в настройки, и вернуть вкладку будет
 * нечем.
 *
 * Список читается на `Dispatchers.IO` и перечитывается на каждый рост
 * [UiTabRegistry.version], поэтому скрытие вкладки из чата видно сразу, без
 * перезапуска.
 */
@Composable
private fun visibleTabs(): List<eu.kanade.presentation.util.Tab> {
    val prefs = remember { Injekt.get<mihon.domain.ocr.service.OcrPreferences>() }
    val aiVisible by prefs.aiTabVisible().collectAsState()
    val context = LocalContext.current
    val version by UiTabRegistry.version.collectAsState()
    val ctorVersion by eu.kanade.tachiyomi.data.ui.UiConstructorStore.version.collectAsState()
    var hidden by remember { mutableStateOf(emptySet<String>()) }
    var order by remember { mutableStateOf(emptyList<String>()) }
    LaunchedEffect(version, ctorVersion) {
        val (h, o) = withContext(Dispatchers.IO) {
            UiTabRegistry.hidden(context) to eu.kanade.tachiyomi.data.ui.UiConstructorStore.tabOrder(context)
        }
        hidden = h
        order = o
    }
    return TABS
        .filterNot { (tab, _) -> tab == UiTab.AI && !aiVisible }
        .filterNot { (tab, _) -> UiTabs.isHidden(tab.id, hidden) }
        .let { list ->
            if (order.isEmpty()) {
                list
            } else {
                list.sortedBy { (tab, _) ->
                    val i = order.indexOf(tab.id)
                    if (i < 0) Int.MAX_VALUE else i
                }
            }
        }
        .map { (_, screen) -> screen }
}

@Composable
override fun Content() {
    // PWA-оболочка Yomihon удалена: приложение всегда работает в нативном
    // интерфейсе, MangaLib PWA живёт как нативная вкладка с мостами.
    val navigator = LocalNavigator.currentOrThrow

    TabNavigator(
        tab = LibraryTab,
        key = TabNavigatorKey,
    ) { tabNavigator ->
        // Provide usable navigator to content screen
        CompositionLocalProvider(LocalNavigator provides navigator) {
            val tabsToShow = visibleTabs()
            // Если текущая вкладка скрыта (напр. AI выключен в настройках),
            // переключаемся на библиотеку, иначе таб-бар остаётся без выделения.
            LaunchedEffect(tabsToShow) {
                if (tabsToShow.none { it::class == tabNavigator.current::class }) {
                    tabNavigator.current = LibraryTab
                }
            }
            Scaffold(
                startBar = {
                    if (isTabletUi()) {
                        NavigationRail {
                            tabsToShow.fastForEach {
                                NavigationRailItem(it)
                            }
                        }
                    }
                },
                bottomBar = {
                    if (!isTabletUi() && !eu.kanade.tachiyomi.ui.webbrowser.WebStore.pipMode.value) {
                        val bottomNavVisible by produceState(initialValue = true) {
                            showBottomNavEvent.receiveAsFlow().collectLatest { value = it }
                        }
                        AnimatedVisibility(
                            visible = bottomNavVisible,
                            enter = expandVertically(),
                            exit = shrinkVertically(),
                        ) {
                            NavigationBar {
                                tabsToShow.fastForEach {
                                    NavigationBarItem(it)
                                }
                            }
                        }
                    }
                },
                contentWindowInsets = WindowInsets(0),
            ) { contentPadding ->
                Column(
                    modifier = Modifier
                        .padding(contentPadding)
                        .consumeWindowInsets(contentPadding),
                ) {
                    Box(modifier = Modifier.weight(1f)) {
                        AnimatedContent(
                            targetState = tabNavigator.current,
                            transitionSpec = {
                                materialFadeThroughIn(initialScale = 1f, durationMillis = TabFadeDuration) togetherWith
                                    materialFadeThroughOut(durationMillis = TabFadeDuration)
                            },
                            label = "tabContent",
                        ) {
                            tabNavigator.saveableState(key = "currentTab", it) {
                                it.Content()
                            }
                        }
                    }
                }
            }
        }

        val goToLibraryTab = { tabNavigator.current = LibraryTab }

        // Контекст для открытия внешних URL во вкладке «Браузер» (web).
        val browserCtx = androidx.compose.ui.platform.LocalContext.current.applicationContext

        BackHandler(enabled = tabNavigator.current != LibraryTab, onBack = goToLibraryTab)

        LaunchedEffect(Unit) {
            launch {
                librarySearchEvent.receiveAsFlow().collectLatest {
                    goToLibraryTab()
                    LibraryTab.search(it)
                }
            }
            launch {
                openTabEvent.receiveAsFlow().collectLatest {
                    tabNavigator.current = when (it) {
                        is Tab.Library -> LibraryTab
                        Tab.Updates -> UpdatesTab
                        Tab.History -> HistoryTab
                        is Tab.Browse -> {
                            if (it.toExtensions) {
                                BrowseTab.showExtension()
                            }
                            BrowseTab
                        }
                        // Открыть сайт во вкладке «Браузер» (web), а не во
                        // встроенном полноэкранном WebView-экране.
                        is Tab.Browser -> {
                            eu.kanade.tachiyomi.ui.webbrowser.WebStore.addTab(
                                browserCtx,
                                it.url,
                                it.title,
                            )
                            eu.kanade.tachiyomi.ui.webbrowser.BrowserTab
                        }
                        Tab.Dictionary -> MoreTab // словарь скрыт из таб-бара
                        is Tab.More -> MoreTab
                        // Вкладку AI можно скрыть в настройках; открывать
                        // несуществующую вкладку нельзя — уходим в библиотеку.
                        Tab.AiChat ->
                            if (Injekt.get<mihon.domain.ocr.service.OcrPreferences>()
                                    .aiTabVisible()
                                    .get()
                            ) {
                                eu.kanade.tachiyomi.ui.aichat.AiChatTab
                            } else {
                                LibraryTab
                            }
                    }

                    if (it is Tab.Library && it.mangaIdToOpen != null) {
                        navigator.push(MangaScreen(it.mangaIdToOpen))
                    }
                    if (it is Tab.More && it.toDownloads) {
                        navigator.push(DownloadQueueScreen)
                    }
                }

metadata.preview:
            }
        }
    }
}

