    if (showTtsDialog) {
        eu.kanade.presentation.reader.TtsSettingsDialog(
            onDismissRequest = { showTtsDialog = false },
            onOpenFullSettings = {
                showTtsDialog = false
                val intent = android.content.Intent(this@ReaderActivity, eu.kanade.tachiyomi.ui.main.MainActivity::class.java).apply {
