    eu.kanade.presentation.reader.components.ReaderFloatingControls(
        visible = state.menuVisible && state.dialog == null,
        readingActive = readingActive,
        manualVoiceMode = manualVoiceMode,
        manualVoiceGender = manualVoiceGender,
