/**
 * Плавающая кнопка поверх ДРУГИХ приложений (v1.9.72).
 *
 * Это НЕ панель, а именно кнопка-пузырёк: тап разворачивает те же кнопки,
 * что в читалке (▶ Голос, ♀ ♂ 🎙, Выбрать, STT, 📋, Копировать, ＋ Словарь,
 * Закрыть). Источник текста — буфер обмена / ручной ввод / STT с микрофона
 * (английская речь игр → текст → русские голоса, реал-тайм).
 *
 * Области: auto — весь экран; manual/fixed — ручное выделение или
 * зафиксированная область (реплики игр), рамка рисуется поверх приложений.
 * В ридере баблы привязаны к панелям манги; здесь страницы нет, поэтому
 * кнопки и стиль — как в читалке, а текст берётся извне.
 *
 * Требует «Показ поверх других приложений» (SYSTEM_ALERT_WINDOW);
 * STT требует RECORD_AUDIO.
 */
class OcrOverlayService : Service() {

    companion object {
        private const val CHANNEL_ID = "ocr_overlay"
        private const val NOTIF_ID = 0x4F43
        private const val ACTION_SPEAK = "eu.kanade.tachiyomi.ocr.OVERLAY_SPEAK"
        private const val ACTION_STT_START = "eu.kanade.tachiyomi.ocr.OVERLAY_STT_START"
        private const val ACTION_STT_STOP = "eu.kanade.tachiyomi.ocr.OVERLAY_STT_STOP"
        private const val ACTION_REFRESH = "eu.kanade.tachiyomi.ocr.OVERLAY_REFRESH"
        private const val ACTION_SELECT_REGION = "eu.kanade.tachiyomi.ocr.OVERLAY_SELECT_REGION"
        private const val EXTRA_TEXT = "text"
        private const val BASE_W_DP = 320f
        private const val BASE_H_DP = 340f
        private const val BTN_DP = 60f

        /** Как часто проверять, не открыто ли наше собственное приложение. */
        private const val FOREGROUND_POLL_MS = 700L

        /** Код ответа на запрос захвата экрана. */
        private const val REQUEST_CAPTURE = 0x4F44

        /** Действие: начать чтение рамки с уже полученным разрешением. */
        private const val ACTION_START_READING = "eu.kanade.tachiyomi.ocr.START_READING"
        private const val EXTRA_RESULT_CODE = "resultCode"
        private const val EXTRA_RESULT_DATA = "resultData"

        fun canDrawOverlays(context: Context): Boolean =
            Settings.canDrawOverlays(context)

        fun requestPermission(context: Context) {
            runCatching {
                context.startActivity(
                    Intent(
                        Settings.ACTION_MANAGE_OVERLAY_PERMISSION,
                        android.net.Uri.parse("package:${context.packageName}"),
                    ).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
                )
            }.onFailure {
                runCatching {
                    context.startActivity(
                        Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION)
                            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
                    )
                }
            }
        }

        fun hasRecordAudio(context: Context): Boolean {
            return context.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO) ==
                PackageManager.PERMISSION_GRANTED
        }

        private fun intentFor(context: Context): Intent =
            Intent(context, OcrOverlayService::class.java)

        private fun startWith(context: Context, intent: Intent) {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                context.startForegroundService(intent)
            } else {
                @Suppress("DEPRECATION")
                context.startService(intent)
            }
        }

        fun start(context: Context) = startWith(context, intentFor(context))

        fun stop(context: Context) {
            runCatching { context.stopService(intentFor(context)) }
        }

        /** Показать текст в бабле и озвучить его поверх любого приложения. */
        fun speak(context: Context, text: String) {
            startWith(
                context,
                intentFor(context).setAction(ACTION_SPEAK).putExtra(EXTRA_TEXT, text),
            )
        }

        fun sttStart(context: Context) {
            startWith(context, intentFor(context).setAction(ACTION_STT_START))
        }

        fun sttStop(context: Context) {
            startWith(context, intentFor(context).setAction(ACTION_STT_STOP))
        }

        /** Перечитать префы (рамка области, слежка за буфером). */
        fun refresh(context: Context) {
            startWith(context, intentFor(context).setAction(ACTION_REFRESH))
        }

        /** Открыть ручной выбор области (нужен запущенный оверлей). */
        fun selectRegion(context: Context) {
            startWith(context, intentFor(context).setAction(ACTION_SELECT_REGION))
        }

        /**
         * Начать чтение рамки с уже полученным разрешением на захват.
         *
         * Разрешение добывает [OcrCaptureActivity]: сервис не может
         * показать системный диалог и получить его результат.
         */
        fun startReading(context: Context, resultCode: Int, data: Intent) {
            startWith(
                context,
                intentFor(context)
                    .setAction(ACTION_START_READING)
                    .putExtra(EXTRA_RESULT_CODE, resultCode)
                    .putExtra(EXTRA_RESULT_DATA, data),
            )
        }
    }

    private lateinit var wm: WindowManager
    private val uiHandler = Handler(Looper.getMainLooper())
    private val prefs: OcrPreferences by lazy { Injekt.get<OcrPreferences>() }

    private var root: FrameLayout? = null
    private var params: WindowManager.LayoutParams? = null
    private var bubbleText: TextView? = null
    private var input: EditText? = null
    private var contentView: LinearLayout? = null
    private var floatButton: TextView? = null
    private var sttButton: Button? = null
    private var regionButton: Button? = null

    private val readEngine by lazy { AutoReadEngine(applicationContext) }
    private var stt: GameSttManager? = null
    private var isSpeaking = false
    private var expandedW = 0
    private var expandedH = 0
    private var ignoreNextClip = false
    private var lastClipText = ""

    // Рамка зафиксированной области (отдельное окно, клики — сквозь).
    private var frameRoot: FrameLayout? = null
    private var frameParams: WindowManager.LayoutParams? = null

    // Селектор области (полноэкранное окно для ручного выделения).
    private var selectorRoot: FrameLayout? = null
    private var selectorDraw: RegionDrawView? = null

package com.yomikai.overlayreader

import android.content.Context
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.RectF
import android.graphics.Typeface
import android.os.Handler
import android.os.Looper
import android.view.MotionEvent
import android.view.View
import kotlin.math.max
import kotlin.math.min

/**
 * Полноэкранный оверлей поверх любого приложения/сайта: затемнение вне рамки,
 * рамка выбора области, тулбар с кнопками и нижняя панель распознанного текста.
 *
 * Вся графика рисуется на Canvas (без внешних UI-библиотек), тач-обработка —
 * на MotionEvent. Кнопки срабатывают по ACTION_UP, рамка перетаскивается и
 * масштабируется за углы/грани.
 */
class OverlayView(
    context: Context,
    private val callback: Callback,
) : View(context) {

    interface Callback {
        fun onScan()
        fun onSpeak()
        fun onCycleVoice()
        fun onOpacity(delta: Float)
        fun onPassThrough()
        fun onResetFrame()
        fun onExit()
        fun onFrameChanged(f: RectFBean)
    }

    enum class Btn(val label: String) {
        SCAN("Скан"),
        SPEAK("Читать"),
        VOICE("Голос"),
        OPAQUE("Прозр"),
        HIDE("Скрыть"),
        EXIT("Выход"),
    }

    private enum class Mode { NONE, MOVE, H_RESIZE, V_RESIZE, CORNER_RESIZE, SCROLL }

    // Публичное состояние, управляется сервисом.
    var scanning: Boolean = false
    var statusText: String = ""
    var resultText: String = ""

    // «Прокачка» кадров на время захвата: оверлей постоянно перерисовывается,
    // поэтому дисплей (а с ним и VirtualDisplay) получает свежие кадры даже на
    // полностью статичном экране. Панели при этом не рисуются, чтобы кадр был
    // чистым.
    private var capturePumping = false
    private val pumpHandler = Handler(Looper.getMainLooper())
    private val pumpRunnable = object : Runnable {
        override fun run() {
            if (capturePumping) {
                invalidate()
                pumpHandler.postDelayed(this, 90)
            }
        }
    }

    fun beginCapturePump() {
        if (capturePumping) return
        capturePumping = true
        pumpHandler.post(pumpRunnable)
    }

    fun endCapturePump() {
        capturePumping = false
        pumpHandler.removeCallbacks(pumpRunnable)
        invalidate()
    }

    private lateinit var frame: RectF
    private var toolbarRect = RectF()
    private var panelRect = RectF()
    private val buttons = ArrayList<Pair<RectF, Btn>>()

    private var mode = Mode.NONE
    private var pressedBtn: Btn? = null
    private var touchX = 0f
    private var touchY = 0f
    private var startFrame = RectF()
    private var scrollLines = 0
    private var lastPanelY = 0f

    private val dimPaint = Paint(Paint.ANTI_ALIAS_FLAG)
    private val borderPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        style = Paint.Style.STROKE
        strokeWidth = dp(2f)
        color = Color.parseColor("#4FC3F7")
    }
    private val handlePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        style = Paint.Style.FILL
        color = Color.parseColor("#4FC3F7")
    }
    private val panelPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        color = Color.parseColor("#E6121420")
    }
    private val toolbarPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        color = Color.parseColor("#F0141A2E")
    }
    private val btnPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        textSize = sp(12f)
        typeface = Typeface.DEFAULT
    }
    private val titlePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        color = Color.WHITE
        textSize = sp(14f)
        typeface = Typeface.DEFAULT_BOLD
    }
    private val statusPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        color = Color.parseColor("#90CAF9")
        textSize = sp(11f)
    }
    private val resultPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        color = Color.WHITE
        textSize = sp(13f)
        typeface = Typeface.SANS_SERIF
    }

    private val density: Float = resources.displayMetrics.density

    private fun dp(v: Float): Float = v * density

    private fun sp(v: Float): Float = v * resources.displayMetrics.scaledDensity

    override fun onSizeChanged(w: Int, h: Int, oldw: Int, oldh: Int) {
        super.onSizeChanged(w, h, oldw, oldh)
        layoutMetrics(w.toFloat(), h.toFloat())
    }

    private var viewH = 0f
    private var viewW = 0f

    private fun layoutMetrics(w: Float, h: Float) {
        viewW = w
        viewH = h
        val toolbarH = dp(44f)
        val panelH = dp(132f)
        toolbarRect = RectF(0f, 0f, w, toolbarH)
        panelRect = RectF(0f, h - panelH, w, h)

        val pref = Prefs.frame()
        frame = RectF(
            pref.left * w,
            pref.top * h,
            pref.right * w,
            pref.bottom * h,
        )
        clampFrame()

        buttons.clear()
        val count = Btn.entries.size
        val bw = w / count
        for (i in Btn.entries.indices) {
            buttons += Pair(
                RectF(i * bw, 0f, (i + 1) * bw, toolbarH),
                Btn.entries[i],
            )
        }
    }

    private fun clampFrame() {
        val minSide = dp(48f)
        val left = max(frame.left, dp(6f))
        val top = max(frame.top, toolbarRect.bottom + dp(6f))
        val right = min(frame.right, viewW - dp(6f))
        val bottom = min(frame.bottom, panelRect.top - dp(6f))
        frame.set(left, top, max(right, left + minSide), max(bottom, top + minSide))
    }

    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)
        if (capturePumping) return

        val alpha = (Prefs.overlayOpacity().coerceIn(0.1f, 0.9f) * 255).toInt()
        dimPaint.color = Color.argb(alpha, 4, 8, 20)

        // Затемнение вокруг рамки.
        canvas.drawRect(0f, 0f, viewW, toolbarRect.bottom, dimPaint)
        canvas.drawRect(0f, toolbarRect.bottom, frame.left, frame.top, dimPaint)
        canvas.drawRect(frame.right, toolbarRect.bottom, viewW, frame.bottom, dimPaint)
        canvas.drawRect(0f, frame.bottom, viewW, viewH, dimPaint)
        canvas.drawRect(frame.left, frame.bottom, frame.right, viewH, dimPaint)
        canvas.drawRect(0f, toolbarRect.bottom, frame.left, viewH, dimPaint)

        // Рамка захвата.
        canvas.drawRoundRect(frame, dp(10f), dp(10f), borderPaint)
        drawHandles(canvas)

        // Тулбар.
        canvas.drawRoundRect(toolbarRect, dp(10f), dp(10f), toolbarPaint)
        drawToolbarButtons(canvas)

        // Панель результата.
        canvas.drawRoundRect(panelRect, dp(10f), dp(10f), panelPaint)
        drawResultPanel(canvas)
    }

    private fun drawToolbarButtons(canvas: Canvas) {
        for ((rect, btn) in buttons) {
            btnPaint.color = if (btn == pressedBtn) Color.parseColor("#FF8A65") else Color.WHITE
            btnPaint.textAlign = Paint.Align.CENTER
            canvas.drawText(btn.label, rect.centerX(), rect.centerY() + dp(4f), btnPaint)
        }
    }

    private fun drawHandles(canvas: Canvas) {
        val hs = dp(16f)
        val half = hs / 2
        for ((cx, cy) in handlePositions()) {
            canvas.drawRect(RectF(cx - half, cy - half, cx + half, cy + half), handlePaint)
        }
    }

    private fun handlePositions(): List<Pair<Float, Float>> {
        val midX = (frame.left + frame.right) / 2
        val midY = (frame.top + frame.bottom) / 2
        return listOf(
            frame.left to frame.top,
            midX to frame.top,
            frame.right to frame.top,
            frame.left to midY,
            frame.right to midY,
            frame.left to frame.bottom,
            midX to frame.bottom,
            frame.right to frame.bottom,
        )
    }

    private fun drawResultPanel(canvas: Canvas) {
        val pad = dp(10f)
        statusPaint.textAlign = Paint.Align.LEFT
        canvas.drawText(
            if (scanning) "Распознаю текст…" else statusText.ifBlank { "Готово" },
            pad,
            panelRect.top + dp(18f),
            statusPaint,
        )
        val maxW = (panelRect.width() - pad * 2).toInt()
        val text = resultText
        if (text.isNotBlank()) {
            val lines = wrapText(resultPaint, text, maxW)
            val lineH = resultPaint.textSize * 1.25f
            val available = panelRect.height() - dp(34f)
            val visible = (available / lineH).toInt().coerceAtLeast(1)
            val maxScroll = max(0, lines.size - visible)
            scrollLines = scrollLines.coerceIn(0, maxScroll)
            var y = panelRect.top + dp(34f) + lineH
            for (i in scrollLines until min(scrollLines + visible, lines.size)) {
                canvas.drawText(lines[i], pad, y, resultPaint)
                y += lineH
            }
        }
    }

    private fun wrapText(paint: Paint, text: String, maxW: Int): List<String> {
        val words = text.split(" ")
        val lines = ArrayList<String>()
        var line = StringBuilder()
        for (word in words) {
            val probe = if (line.isEmpty()) word else "$line $word"
            if (paint.measureText(probe) <= maxW) {
                line = StringBuilder(probe)
            } else {
                if (line.isNotEmpty()) lines += line.toString()
                line = StringBuilder(word)
                while (line.isNotEmpty() && paint.measureText(line.toString()) > maxW) {
                    var cut = line.length
                    while (cut > 1 && paint.measureText(line.substring(0, cut)) > maxW) cut--
                    lines += line.substring(0, cut)
                    line = StringBuilder(line.substring(cut))
                }
            }
        }
        if (line.isNotEmpty()) lines += line.toString()
        return lines
    }

    override fun onTouchEvent(event: MotionEvent): Boolean {
        val x = event.x
        val y = event.y
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> return onDown(x, y)
            MotionEvent.ACTION_MOVE -> { onMove(x, y); return true }
            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                onUp()
                return true
            }
        }
        return true
    }

    private fun onDown(x: Float, y: Float): Boolean {
        touchX = x
        touchY = y
        startFrame.set(frame)
        lastPanelY = y

        for ((rect, btn) in buttons) {
            if (rect.contains(x, y)) {
                pressedBtn = btn
                invalidate()
                return true
            }
        }
        if (panelRect.contains(x, y) && resultText.isNotBlank()) {
            mode = Mode.SCROLL
            return true
        }
        val handle = findHandle(x, y)
        if (handle != null) {
            mode = Mode.CORNER_RESIZE
            handleIndex = handle
            return true
        }
        if (frame.contains(x, y)) {
            mode = Mode.MOVE
            return true
        }
        return true
    }

    private var handleIndex = -1

    private fun findHandle(x: Float, y: Float): Int? {
        val r = dp(20f)
        for ((i, pos) in handlePositions().withIndex()) {
            if (Math.abs(x - pos.first) <= r && Math.abs(y - pos.second) <= r) return i
        }
        return null
    }

    private fun onMove(x: Float, y: Float) {
        val dx = x - touchX
        val dy = y - touchY
        when (mode) {
            Mode.MOVE -> {
                val newLeft = startFrame.left + dx
                val newTop = startFrame.top + dy
                val newRight = startFrame.right + dx
                val newBottom = startFrame.bottom + dy
                val shiftX = newLeft.coerceAtLeast(dp(6f)) - newLeft
                val fixedLeft = newLeft + shiftX
                val fixedRight = newRight + shiftX
                frame.set(
                    fixedLeft,
                    newTop.coerceIn(toolbarRect.bottom + dp(6f), panelRect.top - frame.height() - dp(6f)),
                    fixedRight,
                    newTop.coerceIn(toolbarRect.bottom + dp(6f), panelRect.top - frame.height() - dp(6f)) + frame.height(),
                )
                invalidate()
            }
            Mode.CORNER_RESIZE -> {
                resizeTo(dx, dy)
                invalidate()
            }
            Mode.SCROLL -> {
                val lineH = resultPaint.textSize * 1.25f
                val delta = (y - lastPanelY) / lineH
                scrollLines += delta.toInt()
                lastPanelY = y
                invalidate()
            }
            else -> Unit
        }
        touchX = x
        touchY = y
    }

    private fun resizeTo(dx: Float, dy: Float) {
        val minSide = dp(48f)
        val l = frame.left
        val t = frame.top
        val r = frame.right
        val b = frame.bottom
        when (handleIndex) {
            0 -> { val nl = (startFrame.left + dx).coerceAtMost(r - minSide); frame.set(nl, (startFrame.top + dy).coerceAtMost(b - minSide), r, b) }
            1 -> frame.set(l, (startFrame.top + dy).coerceAtMost(b - minSide), r, b)
            2 -> { val nr = (startFrame.right + dx).coerceAtLeast(l + minSide); frame.set(l, (startFrame.top + dy).coerceAtMost(b - minSide), nr, b) }
            3 -> { val nl = (startFrame.left + dx).coerceAtMost(r - minSide); frame.set(nl, t, r, b) }
            4 -> { val nr = (startFrame.right + dx).coerceAtLeast(l + minSide); frame.set(l, t, nr, b) }
            5 -> { val nl = (startFrame.left + dx).coerceAtMost(r - minSide); val nb = (startFrame.bottom + dy).coerceAtLeast(t + minSide); frame.set(nl, t, r, nb) }
            6 -> frame.set(l, t, r, (startFrame.bottom + dy).coerceAtLeast(t + minSide))
            7 -> { val nb = (startFrame.bottom + dy).coerceAtLeast(t + minSide); frame.set(l, t, (startFrame.right + dx).coerceAtLeast(l + minSide), nb) }
        }
        clampFrame()
    }

    private fun onUp() {
        val btn = pressedBtn
        if (btn != null) {
            perform(btn)
        }
        pressedBtn = null
        mode = Mode.NONE
        callback.onFrameChanged(bean())
        invalidate()
    }

    private fun perform(btn: Btn) {
        when (btn) {
            Btn.SCAN -> callback.onScan()
            Btn.SPEAK -> callback.onSpeak()
            Btn.VOICE -> callback.onCycleVoice()
            Btn.OPAQUE -> callback.onOpacity(0.08f)
            Btn.HIDE -> callback.onPassThrough()
            Btn.EXIT -> callback.onExit()
        }
    }

    private fun bean(): RectFBean = RectFBean(
        left = (frame.left / viewW).coerceIn(0f, 1f),
        top = (frame.top / viewH).coerceIn(0f, 1f),
        right = (frame.right / viewW).coerceIn(0f, 1f),
        bottom = (frame.bottom / viewH).coerceIn(0f, 1f),
    )

    fun resetFrame() {
        frame.set(viewW * 0.06f, toolbarRect.bottom + dp(24f), viewW * 0.94f, viewW * 0.94f * 0.55f + toolbarRect.bottom)
        clampFrame()
        invalidate()
    }
}

package eu.kanade.tachiyomi.ui.reader

import android.content.Context
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.util.AttributeSet
import android.view.MotionEvent
import android.view.View
import android.view.ViewPropertyAnimator
import androidx.core.graphics.withScale
import androidx.core.graphics.withTranslation
import androidx.core.view.isVisible
import eu.kanade.tachiyomi.ui.reader.viewer.ViewerNavigation
import eu.kanade.tachiyomi.ui.reader.viewer.navigation.DisabledNavigation
import tachiyomi.core.common.i18n.stringResource
import kotlin.math.abs

class ReaderNavigationOverlayView(context: Context, attributeSet: AttributeSet) : View(context, attributeSet) {

    private var viewPropertyAnimator: ViewPropertyAnimator? = null

    private var navigation: ViewerNavigation? = null

    fun setNavigation(navigation: ViewerNavigation, showOnStart: Boolean) {
        val firstLaunch = this.navigation == null
        this.navigation = navigation
        invalidate()

        if (isVisible || (!showOnStart && firstLaunch) || navigation is DisabledNavigation) {
            return
        }

        viewPropertyAnimator = animate()
            .alpha(1f)
            .setDuration(FADE_DURATION)
            .withStartAction {
                isVisible = true
            }
            .withEndAction {
                viewPropertyAnimator = null
            }
        viewPropertyAnimator?.start()
    }

    private val regionPaint = Paint()

    private val textPaint = Paint().apply {
        textAlign = Paint.Align.CENTER
        color = Color.WHITE
        textSize = 64f
    }

    private val textBorderPaint = Paint().apply {
        textAlign = Paint.Align.CENTER
        color = Color.BLACK
        textSize = 64f
        style = Paint.Style.STROKE
        strokeWidth = 8f
    }

    override fun onDraw(canvas: Canvas) {
        if (navigation == null) return

        navigation?.getRegions()?.forEach { region ->
            val rect = region.rectF

            // Scale rect from 1f,1f to screen width and height
            canvas.withScale(width.toFloat(), height.toFloat()) {
                regionPaint.color = region.type.color
                drawRect(rect, regionPaint)
            }

            // Don't want scale anymore because it messes with drawText
            // Translate origin to rect start (left, top)
            canvas.withTranslation(x = (width * rect.left), y = (height * rect.top)) {
                // Calculate center of rect width on screen
                val x = width * (abs(rect.left - rect.right) / 2)

                // Calculate center of rect height on screen
                val y = height * (abs(rect.top - rect.bottom) / 2)

                drawText(context.stringResource(region.type.nameRes), x, y, textBorderPaint)
                drawText(context.stringResource(region.type.nameRes), x, y, textPaint)
            }
        }
    }

    override fun performClick(): Boolean {
        super.performClick()

        if (viewPropertyAnimator == null && isVisible) {
            viewPropertyAnimator = animate()
                .alpha(0f)
                .setDuration(FADE_DURATION)
                .withEndAction {
                    isVisible = false
                    viewPropertyAnimator = null
                }
            viewPropertyAnimator?.start()
        }

        return true
    }

    override fun onTouchEvent(event: MotionEvent?): Boolean {
        // Hide overlay if user start tapping or swiping
        performClick()
        return super.onTouchEvent(event)
    }
}

private const val FADE_DURATION = 1000L

package eu.kanade.presentation.reader

import androidx.annotation.ColorInt
import androidx.annotation.IntRange
import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.BlendMode
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.graphicsLayer
import kotlin.math.abs

@Composable
fun ReaderContentOverlay(
    @IntRange(from = -100, to = 100) brightness: Int,
    @ColorInt color: Int?,
    colorBlendMode: BlendMode?,
    modifier: Modifier = Modifier,
) {
    if (brightness < 0) {
        val brightnessAlpha = remember(brightness) {
            abs(brightness) / 100f
        }

        Canvas(
            modifier = modifier
                .fillMaxSize()
                .graphicsLayer {
                    alpha = brightnessAlpha
                },
        ) {
            drawRect(Color.Black)
        }
    }

    if (color != null) {
        Canvas(
            modifier = modifier
                .fillMaxSize(),
        ) {
            drawRect(
                color = Color(color),
                blendMode = colorBlendMode ?: BlendMode.SrcOver,
            )
        }
    }
}

package eu.kanade.presentation.reader

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.Spacer
